package inference

import scala.concurrent.{Future, ExecutionContext}
import scala.collection.concurrent.TrieMap
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.time.{Instant, Duration}

case class InferenceRequest(
  modelId: String,
  inputData: Array[Float],
  timestamp: Long,
  nonce: String,
  signature: String
)

case class InferenceResult(predictions: Array[Float], confidence: Double)

class NonceStore(maxAge: Duration) {
  private val seen = new TrieMap[String, Long]()

  def checkAndStore(nonce: String, timestamp: Long): Boolean = {
    pruneExpired()
    val compositeKey = computeCompositeKey(nonce, timestamp)
    seen.putIfAbsent(compositeKey, timestamp) match {
      case None => true  // nonce was not present, request is fresh
      case Some(_) => false  // replay detected
    }
  }

  private def computeCompositeKey(nonce: String, timestamp: Long): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(nonce.getBytes("UTF-8"))
    digest.update(java.nio.ByteBuffer.allocate(8).putLong(timestamp).array())
    Base64.getEncoder.encodeToString(digest.digest())
  }

  private def pruneExpired(): Unit = {
    val cutoff = Instant.now().minus(maxAge).toEpochMilli
    seen.filterInPlace((_, ts) => ts > cutoff)
  }
}

class SignatureVerifier(secretKey: Array[Byte]) {
  private val algorithm = "HmacSHA256"

  def verify(request: InferenceRequest): Boolean = {
    val payload = buildPayload(request)
    val expectedSig = computeHmac(payload)
    MessageDigest.isEqual(
      expectedSig.getBytes("UTF-8"),
      request.signature.getBytes("UTF-8")
    )
  }

  private def buildPayload(req: InferenceRequest): String = {
    s"${req.modelId}|${req.inputData.mkString(",")}|${req.timestamp}|${req.nonce}"
  }

  private def computeHmac(data: String): String = {
    val mac = Mac.getInstance(algorithm)
    mac.init(new SecretKeySpec(secretKey, algorithm))
    Base64.getEncoder.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }
}

class ModelRegistry {
  private val models = Map(
    "resnet50" -> new MockModel(1000),
    "bert-base" -> new MockModel(768)
  )

  def getModel(id: String): Option[MockModel] = models.get(id)
}

class MockModel(outputDim: Int) {
  def predict(input: Array[Float]): InferenceResult = {
    val predictions = Array.fill(outputDim)(scala.util.Random.nextFloat())
    InferenceResult(predictions, 0.95)
  }
}

class InferenceServer(
  secretKey: Array[Byte],
  timestampTolerance: Duration = Duration.ofMinutes(5),
  nonceTtl: Duration = Duration.ofMinutes(10)
)(implicit ec: ExecutionContext) {

  private val verifier = new SignatureVerifier(secretKey)
  private val nonceStore = new NonceStore(nonceTtl)
  private val registry = new ModelRegistry()

  def handleRequest(request: InferenceRequest): Future[Either[String, InferenceResult]] = {
    Future {
      for {
        _ <- validateTimestamp(request.timestamp)
        _ <- validateSignature(request)
        _ <- validateNonce(request.nonce, request.timestamp)
        result <- executeInference(request)
      } yield result
    }
  }

  private def validateTimestamp(timestamp: Long): Either[String, Unit] = {
    val now = Instant.now().toEpochMilli
    val drift = Math.abs(now - timestamp)
    if (drift <= timestampTolerance.toMillis) Right(())
    else Left(s"Request timestamp outside tolerance window: drift=${drift}ms")
  }

  private def validateSignature(request: InferenceRequest): Either[String, Unit] = {
    if (verifier.verify(request)) Right(())
    else Left("Invalid request signature")
  }

  private def validateNonce(nonce: String, timestamp: Long): Either[String, Unit] = {
    if (nonceStore.checkAndStore(nonce, timestamp)) Right(())
    else Left("Duplicate nonce detected - possible replay attack")
  }

  private def executeInference(request: InferenceRequest): Either[String, InferenceResult] = {
    registry.getModel(request.modelId) match {
      case Some(model) => Right(model.predict(request.inputData))
      case None => Left(s"Model not found: ${request.modelId}")
    }
  }
}
